out=[]; n=0; tot=0
out.append("VIDEO LUNGO 1 - PENSIONE A 64 ANNI NEL 2027: COSA È LEGGE E COSA È SOLO UNA PROPOSTA\n(un blocco = una frase da registrare in CapCut = una o più slide. Per la voce: scrivi \"Inps\" e \"Mai Inps\", così non viene letto lettera per lettera.)\n")
for title,blocks in S:
    out.append("\n=== %s ===" % title)
    for b in blocks:
        n+=1; tot+=len(b); out.append("%d. %s" % (n,b))
sec_chars=tot
out.append("\n\nTotale: %d blocchi, %d caratteri, circa %d parole." % (n,tot,len(" ".join(sum([x[1] for x in S],[])).split())))
out.append("Durata stimata: circa %.1f minuti a 13,6 caratteri al secondo (il tuo ritmo dello short 2); %.1f minuti a 15 caratteri al secondo." % (tot/13.6/60, tot/15/60))
open('copione-blocchi.txt','w',encoding='utf-8').write("\n".join(out))
print("\n".join(out[-3:]))
